        DatasetFilePath filePath = (ReadOnlySpan<byte> key, ulong index, IParquetBufferPool pool, out ParquetBuffer? allocation) =>
            RandomDatasetKeys.FilePath(key, index, out allocation);
        return new Sink(createParts ? Rnd697v.CreateDatasetWriter(route, filePath, files, options)
            : Rnd697v.CreateDatasetWriter(route, files, options));
    }

    sealed class Sink(Rnd697v.DatasetWriter writer) : IRandomDatasetSink
    {
        public void Queue(object row) => writer.Queue((Rnd697v)row);
        public void Dispose() => writer.Dispose();
    }
}